class Calld extends React.Component {
    state = {
        name: "",
        phone: ""
    }

    add =() => {
        console.log(this.state)
    }

    render () {
        return (
            <form action="#" onSubmit={() => this.add}>
                <input type="text" name="name" id="" onChange={(e) => {this.setStatename(e.target.value)}}/>
                <input type="text" name="phone" id="" onChange={(e) => {this.setStatephone(e.target.value)}}/>
                <input type="submit" value="Add" />
            </form>
        )
    }
}

export default Calld
